<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>The Great Wave off Kanagawa — low poly wallpaper</title>
<style>
  html, body { margin:0; height:100%; overflow:hidden; background:#e8d5a3; }
  canvas { display:block; }
  #label {
    position:fixed; left:14px; bottom:12px; z-index:2;
    font-family:"Shippori Mincho", serif; color:#123a5c; opacity:.55;
    font-size:13px; letter-spacing:.06em; pointer-events:none;
  }
</style>
</head>
<body>
<div id="label">The Great Wave off Kanagawa · low poly</div>
<script type="importmap">
{ "imports": { "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js" } }
</script>
<script type="module">
import * as THREE from 'three';

/* ---- palette sampled from the print (public domain, Hokusai) ---- */
const C = {
  skyTop:   0xf2e3b6,
  skyBot:   0xcfc4a0,
  ink:      0x123a5c,
  waveDark: 0x14456e,
  waveMid:  0x2a6ea0,
  waveLite: 0x7fb2d9,
  foam:     0xf4efe2,
  paper:    0xe8d5a3,
  hull:     0xc98f52,
  hullDark: 0x8a5a2b,
  fuji:     0x2f5d8f,
  fujiSnow: 0xf4efe2,
};

const renderer = new THREE.WebGLRenderer({ antialias:true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(C.skyTop);
scene.fog = new THREE.Fog(C.skyBot, 55, 140);

const camera = new THREE.PerspectiveCamera(45, innerWidth/innerHeight, 0.1, 400);
camera.position.set(0, 10, 62);
camera.lookAt(0, 3, 0);

/* flat, print-like lighting */
scene.add(new THREE.AmbientLight(0xffffff, 0.9));
const key = new THREE.DirectionalLight(0xfff4dc, 0.85);
key.position.set(8, 14, 20);
scene.add(key);
const rim = new THREE.DirectionalLight(0x9fc4e8, 0.3);
rim.position.set(-12, 6, -14);
scene.add(rim);

function mat(color) {
  return new THREE.MeshLambertMaterial({ color, flatShading:true });
}

/* ---------- Mt. Fuji: low, small, snow-capped, in the trough, right of centre ---- */
const fuji = new THREE.Group();
const mountain = new THREE.Mesh(new THREE.ConeGeometry(10, 12, 6, 1), mat(C.fuji));
mountain.position.y = 6;
fuji.add(mountain);
const cap = new THREE.Mesh(new THREE.ConeGeometry(3.6, 4.6, 6, 1), mat(C.fujiSnow));
cap.position.y = 9.6;
fuji.add(cap);
fuji.position.set(9, -1.5, -40);
scene.add(fuji);

/* ---------- sea: a big low-poly plane filling the lower half ---------------- */
/* displaced into rolling waves; the great wave crest is added on top. */
const seaGeo = new THREE.PlaneGeometry(160, 90, 40, 24);
seaGeo.rotateX(-Math.PI / 2);
{
  const p = seaGeo.attributes.position;
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i), z = p.getZ(i);
    /* rolling swell: two sines, stronger toward the front */
    const front = 1 - Math.min(1, Math.max(0, (z + 45) / 90)); // 0 back, 1 front
    const y =
      Math.sin(x * 0.18 + z * 0.25) * 1.6 * (0.4 + front) +
      Math.sin(x * 0.45 - z * 0.3) * 0.7 * front;
    p.setY(i, y);
  }
  seaGeo.computeVertexNormals();
}
const sea = new THREE.Mesh(seaGeo, mat(C.waveMid));
scene.add(sea);

/* a darker indigo band further back for depth */
const backGeo = new THREE.PlaneGeometry(160, 30, 30, 6);
backGeo.rotateX(-Math.PI / 2);
{
  const p = backGeo.attributes.position;
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i), z = p.getZ(i);
    p.setY(i, Math.sin(x * 0.2 + z * 0.4) * 1.0 + 1.5);
  }
  backGeo.computeVertexNormals();
}
const backSea = new THREE.Mesh(backGeo, mat(C.waveDark));
backSea.position.z = -30;
scene.add(backSea);

/* ---------- the great wave: a curling crest on the left -------------------- */
/* built from a curling torus + a foam "claw" fan along the crest. */
const greatWave = new THREE.Group();

/* curling body: a torus arc, indigo, opening toward the viewer */
const curl = new THREE.Mesh(
  new THREE.TorusGeometry(8, 3.0, 6, 16, Math.PI * 1.35),
  mat(C.waveDark)
);
